inp=[[6,6,6,6,5,0,5,0],[6,0,0,0,5,5,0,0],[6,0,6,6,0,0,5,5],[0,0,6,0,0,5,5,0]]
out=[[0,0,0,0],[0,0,4,4],[0,4,0,0],[4,0,0,4]]
# pair rows i,i+1 (no wrap) for i 0..2 plus wrap row3->0; collect block tuples and label
def blk(i,j):
    return tuple(inp[i][2*j+k] for k in range(2))+tuple(inp[(i+1)%4][2*j+k] for k in range(2))
blocks={}
for i in range(4):
    for j in range(4):
        b=blk(i,j)
        blocks.setdefault(b,[]).append((i,j,out[i][j]))
for b,v in sorted(blocks.items()):
    print(b,v)

inp=[[6,6,6,6,5,0,5,0],[6,0,0,0,5,5,0,0],[6,0,6,6,0,0,5,5],[0,0,6,0,0,5,5,0]]
H,W=4,8
adj=[]
for i in range(H):
    for j in range(W):
        for di,dj in ((0,1),(1,0)):
            ni,nj=i+di,j+dj
            if ni<H and nj<W:
                a,b=inp[i][j],inp[ni][nj]
                if {a,b}=={6,5}: adj.append(((i,j),(ni,nj)))
print(adj)
# diagonal
diag=[]
for i in range(H):
    for j in range(W):
        for di,dj in ((1,1),(1,-1)):
            ni,nj=i+di,j+dj
            if 0<=ni<H and 0<=nj<W and {inp[i][j],inp[ni][nj]}=={6,5}: diag.append(((i,j),(ni,nj)))
print(diag)
